<?php declare(strict_types=1);
function ownCashClubs(array$f):array{$clubs=array_values($f['data']['profile_clubs']);if(count($clubs)!==8)throw new RuntimeException('Eight actual own cash clubs required');foreach($clubs as$i=>$club)if($club!=='own-cash-ui-'.($i+1))throw new RuntimeException('Exact own cash club required');return$clubs;}
function ownCashDatabase(PDO$db):array{$c=Kulturhus\Native\TestSupport::config();if(($c['owner']??'')!=='isolated-native-ci'||($c['label']??'')!=='native-balance-own-movement-interface'||($c['host']??'')!=='127.0.0.1'||($c['port']??0)!==13371||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',$c['database']??'')||$db->query('SELECT DATABASE()')->fetchColumn()!==$c['database']||(int)$db->query('SELECT MAX(version)FROM schema_migrations')->fetchColumn()!==135)throw new RuntimeException('Exact actual own cash journal database required');return$c;}
function ownCashFilter(array$f):callable{$clubs=ownCashClubs($f);$baseline=$f['data']['proof_baseline'];$marks=implode(',',array_fill(0,8,'?'));return static fn(string$table):array=>match($table){'balance_period_events'=>[' WHERE club_id NOT IN('.$marks.') OR period_id<>? OR revision<=?',[...$clubs,$f['data']['period_id'],2]],'balance_period_sources'=>[' WHERE club_id NOT IN('.$marks.')',$clubs],'audit_events'=>[' WHERE sequence<=?',[$baseline['audit']]],default=>['',[]]};}
function ownCashRows(PDO$db,string$table,array$f):array{
 if(!in_array($table,['balance_period_events','balance_period_sources','audit_events'],true))throw new RuntimeException('Exact accepted cash source table required');$q=$db->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);$columns=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION");$q->execute([$table]);$primary=$q->fetchAll(PDO::FETCH_COLUMN);if(!$columns||!$primary)throw new RuntimeException('Actual cash source columns and primary keys required');$clubs=ownCashClubs($f);$marks=implode(',',array_fill(0,8,'?'));[$where,$args]=match($table){'balance_period_events'=>['club_id IN('.$marks.')AND period_id=? AND revision>2',[...$clubs,$f['data']['period_id']]],'balance_period_sources'=>['club_id IN('.$marks.')',$clubs],'audit_events'=>['sequence>?',[$f['data']['proof_baseline']['audit']]]};$quote=static fn(string$v):string=>'`'.str_replace('`','``',$v).'`';$q=$db->prepare('SELECT '.implode(',',array_map($quote,$columns)).' FROM '.$quote($table).' WHERE '.$where.' ORDER BY '.implode(',',array_map($quote,$primary)));$q->execute($args);return$q->fetchAll(PDO::FETCH_ASSOC);
}
function ownCashJournalProof(array$f):void{
 $profile=$_SERVER['HTTP_X_OWNED_CASH_PROFILE']??null;if(PHP_SAPI!=='cli-server'||($_SERVER['REQUEST_METHOD']??'')!=='GET'||!is_string($profile)||!preg_match('/\A[1-8]\z/D',$profile)||!is_string($_SERVER['HTTP_X_OWNED_CASH_JOURNAL_PROOF']??null)||!hash_equals($f['data']['proof_nonce']??'',$_SERVER['HTTP_X_OWNED_CASH_JOURNAL_PROOF'])){http_response_code(403);exit;}ini_set('log_errors','1');require_once dirname(__DIR__,2).'/src/bootstrap.php';require_once __DIR__.'/original-database-hash.php';$db=Kulturhus\Native\TestSupport::db();ownCashDatabase($db);$tables=array_values(array_diff($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN),['native_auth_sessions','native_auth_limits','native_language_preferences']));header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');echo json_encode(['protected_sha256'=>ownOriginalDatabaseHash($db,$tables,ownCashFilter($f)),'protected_tables'=>count($tables),'records'=>ownCashRows($db,'balance_period_events',$f),'anchors'=>ownCashRows($db,'balance_period_sources',$f),'audits'=>ownCashRows($db,'audit_events',$f),'profile'=>(int)$profile,'state'=>(new Kulturhus\Verein\BalancePeriodLedger($db,'ownmv-'.$profile.'-finance'))->report($f['data']['period_id'])],JSON_THROW_ON_ERROR),PHP_EOL;
